import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getResearchInsights } from '../api/api';
import SimpleButton from '../components/SimpleButton';

const SimpleResearchInsights = () => {
  const navigate = useNavigate();
  const [researchData, setResearchData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadResearchData = async () => {
      try {
        // First check if we have AI analysis from uploaded file
        const storedCompanyData = localStorage.getItem('companyData');

        if (storedCompanyData) {
          const companyData = JSON.parse(storedCompanyData);
          console.log('Research: Using AI analysis from upload');

          // Check if we have research data from the upload
          if (companyData.ai_analysis && companyData.ai_analysis.research_data) {
            setResearchData(companyData.ai_analysis.research_data);
            console.log('Research: AI research data set from upload');
            setLoading(false);
            return;
          }

          // If no research data from upload, perform research for this company
          console.log('Research: No research data in upload, performing new research');
          try {
            const response = await getResearchInsights();
            if (response.status === 'success') {
              setResearchData(response.research_data);
              console.log('Research: API research data loaded');
            }
          } catch (apiErr) {
            console.error('Research: API call failed, using fallback');
            setError('Research API unavailable - showing limited data');
          }
        } else {
          // No company data, use API
          console.log('Research: No company data found, using API');
          const response = await getResearchInsights();
          if (response.status === 'success') {
            setResearchData(response.research_data);
          }
        }
      } catch (err) {
        console.error('Research: Error loading data:', err);
        setError('Failed to load research data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadResearchData();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-lg text-gray-600">Loading research insights...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-red-600 mb-2">Error Loading Research</h2>
          <p className="text-gray-600">{error}</p>
          <SimpleButton onClick={() => window.location.reload()} className="mt-6">
            Try Again
          </SimpleButton>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen py-8">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">Research Insights</h1>
              <p className="text-lg text-gray-600">Comprehensive market and company research analysis</p>
            </div>
            <div className="flex space-x-3">
              <SimpleButton onClick={() => navigate('/dashboard')} className="bg-blue-600 hover:bg-blue-700">
                Back to Dashboard
              </SimpleButton>
              <SimpleButton onClick={() => navigate('/cam-preview')} className="bg-green-600 hover:bg-green-700">
                Generate CAM
              </SimpleButton>
            </div>
          </div>
        </div>

        {researchData && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Handle new research structure with research_summary */}
            {researchData.research_summary ? (
              <>
                {/* News Sentiment */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">📰</span>
                    News Sentiment Analysis
                  </h3>
                  <div className="space-y-4">
                    <div className={`p-4 rounded-lg ${
                      researchData.research_summary.news_sentiment.sentiment === 'Positive' ? 'bg-green-50' :
                      researchData.research_summary.news_sentiment.sentiment === 'Negative' ? 'bg-red-50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Sentiment</span>
                        <span className={`font-bold ${
                          researchData.research_summary.news_sentiment.sentiment === 'Positive' ? 'text-green-600' :
                          researchData.research_summary.news_sentiment.sentiment === 'Negative' ? 'text-red-600' : 'text-gray-600'
                        }`}>
                          {researchData.research_summary.news_sentiment.sentiment}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Sentiment Score</span>
                        <span className="font-bold text-blue-600">
                          {researchData.research_summary.news_sentiment.score?.toFixed(2) || '0.00'}
                        </span>
                      </div>
                      <div className="text-sm text-gray-700">
                        Based on {researchData.research_summary.news_sentiment.total_articles_analyzed || 0} news articles
                      </div>
                    </div>
                  </div>
                </div>

                {/* Litigation Analysis */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">⚖️</span>
                    Litigation Analysis
                  </h3>
                  <div className="space-y-4">
                    <div className={`p-4 rounded-lg ${
                      researchData.research_summary.litigation_data.risk_assessment === 'High' ? 'bg-red-50' :
                      researchData.research_summary.litigation_data.risk_assessment === 'Medium' ? 'bg-yellow-50' : 'bg-green-50'
                    }`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Risk Assessment</span>
                        <span className={`font-bold ${
                          researchData.research_summary.litigation_data.risk_assessment === 'High' ? 'text-red-600' :
                          researchData.research_summary.litigation_data.risk_assessment === 'Medium' ? 'text-yellow-600' : 'text-green-600'
                        }`}>
                          {researchData.research_summary.litigation_data.risk_assessment}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Total Cases</span>
                        <span className="font-bold text-orange-600">
                          {researchData.research_summary.litigation_data.total_cases || 0}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Active Cases</span>
                        <span className="font-bold text-red-600">
                          {researchData.research_summary.litigation_data.active_cases || 0}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Industry Analysis */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">🏭</span>
                    Industry Analysis
                  </h3>
                  <div className="space-y-4">
                    <div className={`p-4 rounded-lg ${
                      researchData.research_summary.industry_analysis.outlook === 'Positive' ? 'bg-green-50' :
                      researchData.research_summary.industry_analysis.outlook === 'Negative' ? 'bg-red-50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Industry Outlook</span>
                        <span className={`font-bold ${
                          researchData.research_summary.industry_analysis.outlook === 'Positive' ? 'text-green-600' :
                          researchData.research_summary.industry_analysis.outlook === 'Negative' ? 'text-red-600' : 'text-gray-600'
                        }`}>
                          {researchData.research_summary.industry_analysis.outlook}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Growth Rate</span>
                        <span className="font-bold text-blue-600">
                          {researchData.research_summary.industry_analysis.growth_rate || 'Unknown'}
                        </span>
                      </div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Market Position</span>
                        <span className="font-bold text-purple-600">
                          {researchData.research_summary.industry_analysis.market_position || 'Unknown'}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Risk Signals */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">🚨</span>
                    Risk Signals
                  </h3>
                  <div className="space-y-3">
                    {researchData.research_summary.risk_signals && researchData.research_summary.risk_signals.length > 0 ? (
                      researchData.research_summary.risk_signals.slice(0, 6).map((signal, index) => (
                        <div key={index} className="flex items-start space-x-3 p-3 bg-red-50 rounded-lg border-l-4 border-red-400">
                          <div className="text-2xl">⚠️</div>
                          <p className="text-sm text-gray-700">{signal}</p>
                        </div>
                      ))
                    ) : (
                      <div className="text-center py-8">
                        <div className="text-4xl mb-4">✅</div>
                        <p className="text-gray-600">No significant risk signals identified</p>
                      </div>
                    )}
                  </div>
                </div>
              </>
            ) : (
              /* Fallback to old structure for backward compatibility */
              <>
                {/* Promoter Risk (Old Structure) */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">👤</span>
                    Promoter Risk Analysis
                  </h3>
                  <div className="space-y-4">
                    <div className="bg-yellow-50 p-4 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Risk Level</span>
                        <span className="font-bold text-yellow-600">{researchData.promoter_risk || 'Medium'}</span>
                      </div>
                      <p className="text-sm text-gray-700">
                        Based on background checks and financial history
                      </p>
                    </div>
                  </div>
                </div>

                {/* Sector Outlook (Old Structure) */}
                <div className="bg-white rounded-lg shadow-md p-8">
                  <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center">
                    <span className="text-2xl mr-2">📈</span>
                    Sector Outlook
                  </h3>
                  <div className="space-y-4">
                    <div className={`p-4 rounded-lg ${
                      researchData.sector_outlook === 'Positive' ? 'bg-green-50' :
                      researchData.sector_outlook === 'Negative' ? 'bg-red-50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-gray-600">Outlook</span>
                        <span className={`font-bold ${
                          researchData.sector_outlook === 'Positive' ? 'text-green-600' :
                          researchData.sector_outlook === 'Negative' ? 'text-red-600' : 'text-gray-600'
                        }`}>
                          {researchData.sector_outlook || 'Stable'}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SimpleResearchInsights;
